var P1={ "fifo-trace": "A queue is FIFO: the first enqueued is the first dequeued. This drill gives you a sequence of {nops} enqueue/dequeue operations and asks for two things: the values that came out (in order) and what remains in the queue. Trace it with a pencil: write the queue contents after every step." };
var P2={ "fifo-trace": "The discipline to practice is end-awareness — enqueues go to the back, dequeues come from the front, and the two ends never mix. Dequeueing an empty queue is an error, so a valid sequence never asks for more dequeues than prior enqueues; the drill input respects that. Step through slowly: the most common mistake is dequeuing from the wrong end." };
var P3={ "fifo-trace": "The dequeued values, in order, are {dequeued}; the queue holds {remaining} afterwards. If your hand-trace matches, your FIFO discipline is solid — this exact skill (tracking both ends through a mixed sequence) is what BFS correctness rests on." };
var PYPROG={ "fifo-trace": "TRACE_INPUT = {input}\nfrom collections import deque\nq, out = deque(), []\nfor op in TRACE_INPUT['ops']:\n    if op[0] == 'enq':\n        q.append(op[1])\n    else:\n        out.append(q.popleft())   # FIFO: oldest first\nprint({'dequeued': out, 'remaining': list(q)})\n" };
